function paint(rows: string[]): HTMLCanvasElement {
  const w = Math.max(...rows.map(r => r.length));
  const p = new PixelCanvas(w, rows.length);
  const each = (glow: boolean) =>
    rows.forEach((r, y) => [...r].forEach((ch, x) => ch !== '.' && GLOW.includes(ch) === glow && p.px(x, y, PAL[ch])));
  each(false);
  p.outline('auto', 0.3);
  each(true);
  return p.toCanvas();
}

export const SKILL_ICONS: Record<string, () => HTMLCanvasElement> = {
  thrust: () => paint(THRUST),
  slash: () => paint(SLASH),
  rend: () => paint(REND),
  whirlwind: () => paint(WHIRLWIND),
  warcry: () => paint(WARCRY),
  charge: () => paint(CHARGE),
  interrupt: () => paint(INTERRUPT),
  mortal: () => paint(MORTAL),
  mount: () => paint(MOUNT),
  sunder: () => paint(SUNDER),
  deathblow: () => paint(DEATHBLOW),
  bloodrage: () => paint(BLOODRAGE),
  berserk: () => paint(BERSERK),
  shieldbash: () => paint(SHIELDBASH),
  laststand: () => paint(LASTSTAND),
  secondwind: () => paint(SECONDWIND),
};
